// Variabili SDA di libogc relative all'arena MEM1
static void ApplyArenaHiSdaPatches(uint32_t r13) {
    if (r13 == 0) return;
    uint32_t newHi = 0x80000000 + (uint32_t)MEM1_SIZE - 0x1000;
    g_Memory.Write32(r13 + (uint32_t)(int32_t)-32108, newHi);
}

static void ApplyInitialSdaPatches(uint32_t r13) {
    if (r13 == 0) return;
    ApplyArenaHiSdaPatches(r13);
    g_Memory.Write32(r13 + (uint32_t)(int32_t)-32104, g_Memory.arenaLo);
}

